questions.questionText:
¿Qué valor tiene pasos al final?
enum Estado { Quieto, Corriendo, Saltando }
Estado e = Estado.Quieto;
int pasos = 0;
while (e != Estado.Saltando)
{
    switch (e)
    {
        case Estado.Quieto: e = Estado.Corriendo; break;
        case Estado.Corriendo: e = Estado.Saltando; break;
    }
    pasos++;
}

